insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000006409', 'Crescente e convergente para $e$.', 'Considere $f(x)=x\ln(1+1/x)$. Sua derivada é $\ln(1+1/x)-1/(x+1)>0$, pois $\ln(1+t)>t/(1+t)$ para $t>0$. Assim $a_n=e^{f(n)}$ cresce. Como $f(n)\to1$, temos $a_n\to e$.') on conflict do nothing;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000064090', '40000000-0000-4000-8000-000000006409', 'Passo 1', 'Considere $f(x)=x\ln(1+1/x)$. Sua derivada é $\ln(1+1/x)-1/(x+1)>0$, pois $\ln(1+t)>t/(1+t)$ para $t>0$.', '1') on conflict do nothing;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000064091', '40000000-0000-4000-8000-000000006409', 'Passo 2', 'Assim $a_n=e^{f(n)}$ cresce. Como $f(n)\to1$, temos $a_n\to e$.', '2') on conflict do nothing;
